{"script":"() => {
  // Try to find the Turnstile widget
  const widgets = document.querySelectorAll('[id^="cf-chl-widget"], .cf-turnstile, iframe[src*="challenges.cloudflare.com"]');

  // Look for the visible checkbox area
  const checkboxes = document.querySelectorAll('input[type="checkbox"]');
  const result = {
    widgetCount: widgets.length,
    checkboxCount: checkboxes.length,
    details: []
  };

  checkboxes.forEach((cb, i) => {
    const rect = cb.getBoundingClientRect();
    result.details.push({
      index: i,
      ariaLabel: cb.getAttribute('aria-label'),
      visible: rect.width > 0 && rect.height > 0,
      rect: {left: rect.left, top: rect.top, width: rect.width, height: rect.height},
      checked: cb.checked
    });
  });

  return result;
}"}

