{"script":"() => {
  const cb = document.querySelector('input[type="checkbox"]');
  if (!cb) return 'no checkbox';

  // Get the iframe parent (Turnstile)
  const widget = cb.closest('[id^="cf-chl-widget"]') || cb.closest('.cf-turnstile') || cb.parentElement;

  // Try to find a clickable parent or the actual Turnstile widget
  let clickTarget = cb;

  // The Turnstile widget usually wraps the checkbox
  const rect = cb.getBoundingClientRect();

  // Try clicking at the center of the checkbox visually
  const x = rect.left + rect.width / 2;
  const y = rect.top + rect.height / 2;

  // Find the actual clickable element (might be wrapped in a label or div)
  const parent = cb.parentElement;
  if (parent) {
    parent.click();
  }

  return {
    rect: rect,
    checked: cb.checked,
    parentTag: parent ? parent.tagName : null
  };
}"}

